import itertools
# extended binary Golay code via QR code length 23
Q={(i*i)%23 for i in range(1,23)}
gen=[0]*23
# generator polynomial approach: use codewords = span of cyclic shifts of vector with 1 at {0} ∪ N? use known: QR code generated by idempotent
gpoly=[0,2,4,5,6,10,11]
base=[1 if i in gpoly else 0 for i in range(23)]
vecs=[]
for s in range(23):
    v=[base[(i-s)%23] for i in range(23)]
    v.append(sum(v)%2)
    vecs.append(int(''.join(map(str,v)),2))
# span
basis=[]
for v in vecs:
    for b in basis:
        v=min(v,v^b)
    if v: basis.append(v); basis.sort(reverse=True)
print(len(basis))
code={0}
for b in basis:
    code|={c^b for c in code}
w=[bin(c).count('1') for c in code]
from collections import Counter
print(Counter(w))
octads=[c for c in code if bin(c).count('1')==8]
p,q=0,1
bits=lambda c:[i for i in range(24) if c>>(23-i)&1]
hexads=[]
for o in octads:
    b=bits(o)
    if p in b and q in b:
        hexads.append(frozenset(x for x in b if x not in (p,q)))
print(len(hexads))
pts=list(range(2,24))
V=['inf']+pts+hexads
n=len(V)
def adj(a,b):
    if a==b: return False
    if a=='inf': return isinstance(b,int)
    if b=='inf': return isinstance(a,int)
    if isinstance(a,int) and isinstance(b,int): return False
    if isinstance(a,int): return a in b
    if isinstance(b,int): return b in a
    return len(a&b)==0
A=[[adj(V[i],V[j]) for j in range(n)] for i in range(n)]
ok=True
for i in range(n):
    assert sum(A[i])==22
    for j in range(i+1,n):
        c=sum(A[i][k] and A[j][k] for k in range(n))
        if A[i][j] and c!=0: ok=False
        if not A[i][j] and c!=6: ok=False
print('srg',ok)
rows=[sum(1<<j for j in range(n) if A[i][j]) for i in range(n)]
open('rows.txt','w').write('\n'.join(map(str,rows)))

hm=[sum(1<<(p-2) for p in h) for h in hexads]
# sort for readability
hm.sort()
def adjN(i,j):
    if i==j: return False
    if i==0: return 1<=j<=22
    if i<=22: return j==0 or (j>=23 and (hm[j-23]>>(i-1))&1==1)
    return (1<=j<=22 and (hm[i-23]>>(j-1))&1==1) or (j>=23 and hm[i-23]&hm[j-23]==0)
rows2=[sum(1<<j for j in range(100) if adjN(i,j)) for i in range(100)]
for i in range(100):
    for j in range(100):
        assert adjN(i,j)==adjN(j,i)
        c=bin(rows2[i]&rows2[j]).count('1')
        e=22 if i==j else (0 if adjN(i,j) else 6)
        assert c==e,(i,j,c,e)
print("ok2")
open('hexads.lean','w').write("[" + ",\n  ".join(", ".join(str(x) for x in hm[k:k+7]) for k in range(0,77,7)) + "]")
open('rows.lean','w').write("[" + ",\n  ".join(", ".join(str(x) for x in rows2[k:k+4]) for k in range(0,100,4)) + "]")
# steiner check
import itertools
cnt=0
for t in itertools.combinations(range(22),3):
    m=sum(1<<x for x in t)
    assert sum(1 for h in hm if h&m==m)==1
print("steiner ok")
